package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.propulsion.*;
import io.github.astelev.around_planet.client.PropulsionScreen;
import io.github.astelev.around_planet.AroundPlanet;
import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.api.distmarker.Dist;
@EventBusSubscriber(modid="around_planet",value=Dist.CLIENT)
public final class PropulsionClientSmoke {
    private static int ticks;
    @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("around_planet.propulsionSmoke"))return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;ticks++;
        if(ticks==20)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.setNoGravity(true);p.getAbilities().flying=true;p.onUpdateAbilities();p.teleportTo(p.serverLevel(),2,201,3,java.util.Set.of(),180,34);var l=p.serverLevel();l.setDayTime(6000);p.getInventory().setItem(8,ItemStack.EMPTY);p.getInventory().selected=8;p.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);l.setBlockAndUpdate(new BlockPos(0,200,0),PropulsionRegistry.ENGINE.get().defaultBlockState());l.setBlockAndUpdate(new BlockPos(2,200,0),PropulsionRegistry.RSU.get().defaultBlockState());l.setBlockAndUpdate(new BlockPos(4,200,0),PropulsionRegistry.DAMPER.get().defaultBlockState());var be=(PropulsionBlockEntity)l.getBlockEntity(new BlockPos(4,200,0));be.energy.stored(0);be.energy.receiveEnergy(100000,false);var rsu=(PropulsionBlockEntity)l.getBlockEntity(new BlockPos(2,200,0));rsu.configure(1000);for(int i=0;i<8;i++)rsu.frequency(i,ItemStack.EMPTY);Item[] items={Items.DIAMOND,Items.IRON_INGOT,Items.EMERALD,Items.GOLD_INGOT,Items.REDSTONE,Items.COPPER_INGOT,Items.LAPIS_LAZULI,Items.AMETHYST_SHARD};for(int i=0;i<8;i++)p.getInventory().setItem(i,new ItemStack(items[i]));p.inventoryMenu.broadcastChanges();});
        if(ticks==60){mc.player.getInventory().selected=0;var pos=new BlockPos(2,200,0);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),Direction.UP,pos,false);if(mc.level.getBlockState(pos).useWithoutItem(mc.level,mc.player,hit)!=net.minecraft.world.InteractionResult.PASS||mc.screen!=null)throw new AssertionError("Held item opened configuration");}
        if(ticks==80){open(mc,2);var buttons=mc.screen.children().stream().filter(net.minecraft.client.gui.components.Button.class::isInstance).map(net.minecraft.client.gui.components.Button.class::cast).toList();for(int i=0;i<8;i++){buttons.get(i).onPress();buttons.get(9+i).onPress();}var slider=mc.screen.children().stream().filter(net.minecraft.client.gui.components.AbstractSliderButton.class::isInstance).map(net.minecraft.client.gui.components.AbstractSliderButton.class::cast).findFirst().orElseThrow();slider.mouseClicked(slider.getX()+slider.getWidth()*.7,slider.getY()+10,0);slider.mouseReleased(0,0,0);}
        if(ticks==120){var be=(PropulsionBlockEntity)mc.level.getBlockEntity(new BlockPos(2,200,0));if(!be.frequency(0).is(Items.DIAMOND)||!be.frequency(7).is(Items.AMETHYST_SHARD)||be.thrust()==1000)throw new AssertionError("RSU ghost frequency or slider packet failed");snap(mc,"rsu-alpha19.png");AroundPlanet.LOGGER.info("PROPULSION_UI RSU PASS: eight server-authorized ghost slots and thrust slider");}
        if(ticks==140)open(mc,0);if(ticks==160)snap(mc,"creative-thruster-alpha19.png");if(ticks==180)open(mc,4);if(ticks==200){var be=(PropulsionBlockEntity)mc.level.getBlockEntity(new BlockPos(4,200,0));if(be.energy.getEnergyStored()!=100000)throw new AssertionError("Client FE state missing");snap(mc,"inertia-damper-alpha19.png");AroundPlanet.LOGGER.info("PROPULSION_UI PASS: engine and FE damper screens");}if(ticks==205){mc.options.fov().set(35);mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();p.teleportTo(p.serverLevel(),2.5,200,1.8,java.util.Set.of(),180,49);});}if(ticks==220)mc.setScreen(null);if(ticks==225)snap(mc,"propulsion-models-alpha19.png");if(ticks==226)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();p.getInventory().setItem(8,new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("create:wrench"))));p.inventoryMenu.broadcastChanges();});if(ticks==240){mc.player.getInventory().selected=8;var pos=new BlockPos(2,200,0);var hit=new net.minecraft.world.phys.BlockHitResult(new net.minecraft.world.phys.Vec3(2.5,200.125,.5),Direction.EAST,pos,false);mc.gameMode.useItemOn(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND,hit);if(mc.screen!=null)throw new AssertionError("Wrench opened configuration");}if(ticks==260){var pos=new BlockPos(2,200,0);if(mc.level.getBlockState(pos).getValue(io.github.astelev.around_planet.sensor.OrbitalSensorBlock.FACING)==Direction.UP)throw new AssertionError("Create wrench did not rotate the client RSU");AroundPlanet.LOGGER.info("INSTRUMENT_INTERACTION PASS: held items pass, empty-hand UI opens, native Create wrench rotates without a screen");mc.options.fov().set(70);mc.stop();}
    }
    private static void open(Minecraft mc,int x){mc.player.getInventory().selected=8;var p=new BlockPos(x,200,0);var hit=new net.minecraft.world.phys.BlockHitResult(new net.minecraft.world.phys.Vec3(x+.5,200.125,.5),Direction.UP,p,false);mc.gameMode.useItemOn(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND,hit);if(!(mc.screen instanceof PropulsionScreen))throw new AssertionError("Empty-hand interaction failed to open configuration");}
    private static void snap(Minecraft mc,String name){net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),message->{});}
}
